using Dip.Domain.Entities; using Dip.Domain.ValueObjects; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; namespace Dip.Infrastructure.Persistence.Configurations; public sealed class ProjectConfiguration:IEntityTypeConfiguration<Project>{public void Configure(EntityTypeBuilder<Project>b){b.ToTable("projects");b.HasKey(x=>x.Id);b.Property(x=>x.Name).HasMaxLength(120).IsRequired();b.Property(x=>x.RepositoryUrl).HasMaxLength(500).IsRequired();b.Property(x=>x.DefaultBranch).HasMaxLength(200).IsRequired();b.Property(x=>x.HealthScore).HasConversion(x=>x.Value,x=>new HealthScore(x)).HasPrecision(5,2);}} public sealed class PipelineRunConfiguration:IEntityTypeConfiguration<PipelineRun>{public void Configure(EntityTypeBuilder<PipelineRun>b){b.ToTable("pipeline_runs");b.HasKey(x=>x.Id);b.Property(x=>x.CommitSha).HasConversion(x=>x.Value,x=>new CommitSha(x)).HasMaxLength(64);b.Property(x=>x.CollectorType).HasMaxLength(100);b.Property(x=>x.CollectorVersion).HasMaxLength(50);b.HasIndex(x=>new{x.ProjectId,x.CommitSha,x.CollectorType});}} public sealed class MetricConfiguration:IEntityTypeConfiguration<Metric>{public void Configure(EntityTypeBuilder<Metric>b){b.ToTable("metrics");b.HasKey(x=>x.Id);b.Property(x=>x.Name).HasMaxLength(120);b.Property(x=>x.Unit).HasMaxLength(30);b.HasIndex(x=>new{x.PipelineRunId,x.Name});}} public sealed class QualityIssueConfiguration:IEntityTypeConfiguration<QualityIssue>{public void Configure(EntityTypeBuilder<QualityIssue>b){b.ToTable("quality_issues");b.HasKey(x=>x.Id);b.Property(x=>x.Category).HasMaxLength(80);b.Property(x=>x.Title).HasMaxLength(200);b.Property(x=>x.Description).HasMaxLength(4000);b.Property(x=>x.Source).HasMaxLength(1000);b.HasIndex(x=>new{x.ProjectId,x.Severity,x.Status});}}